const icon=(name,size=18)=>`<svg aria-hidden="true" class="svg-icon" width="${size}" height="${size}" viewBox="0 0 24 24">${pathSvg[name]||pathSvg.grid}</svg>`
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))
const fmtDate=s=>s?new Date(s).toLocaleDateString('ar-EG',{day:'numeric',month:'short',year:'numeric'}):'—'
const fmtNum=n=>new Intl.NumberFormat('ar-EG').format(n||0)
const fmtMinutes=n=>!n?'٠ دقيقة':`${fmtNum(Math.floor(n/60))} ساعة ${n%60?`و${fmtNum(n%60)} دقيقة`:''}`.replace(/^٠ ساعة /,'')
function localMonth(){let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function localTime(delta=0){let d=new Date(Date.now()+delta*60000);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function notice(s,isError=false){toastBox.textContent=s;toastBox.className=isError?'show error':'show';clearTimeout(notice.timer);notice.timer=setTimeout(()=>{toastBox.className=''},5000)}
const me=()=>state.auth?.user,center=()=>state.auth?.center,manager=()=>['center_admin','supervisor'].includes(me()?.role),owner=()=>me()?.role==='center_admin',superadmin=()=>me()?.role==='superadmin'
const photoSrc=id=>`/api/media/staff/${encodeURIComponent(id)}?v=${state.photoVersion||0}`
function avatar(person,cls=''){const isSupervisor=person?.role==='supervisor',isFemale=person?.gender==='female';const tone=isSupervisor?'avatar-green':isFemale?'avatar-pink':'avatar-blue';const crown=isSupervisor?'<span class="avatar-crown" aria-label="مشرف">♛</span>':'';return `<span class="avatar ${tone} ${cls}" aria-label="${esc(person?.name||'مستخدم')}"><svg viewBox="0 0 48 48" role="img" aria-hidden="true"><circle cx="24" cy="16" r="9.2" fill="currentColor" opacity=".82"/><path d="M6 43c0-11 8-18 18-18s18 7 18 18" fill="currentColor" opacity=".82"/></svg>${crown}</span>`}
function pageHead(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="page-actions">${actions}</div></div>`}
function btn(label,action,variant='primary',extra=''){return `<button class="btn btn-${variant}" type="button" data-action="${action}" ${extra}>${label}</button>`}
const empty=(title,desc='ستظهر البيانات هنا بعد إضافتها')=>`<div class="empty"><div class="big">✧</div><b>${title}</b><span>${desc}</span></div>`
function table(headers,rows,emptyText){if(!rows.length)return empty(emptyText);return `<div class="table-overflow"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function stat(label,value,foot,ico='chart',color=''){return `<article class="metric"><div class="metric-icon ${color}">${icon(ico)}</div><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></article>`}
function supportMessage(){const u=me(),c=center();if(!u)return 'مرحبًا، أنا ممثل عن مركز تأهيل وأرغب في معرفة تفاصيل الانضمام إلى منصة تأهيل +. أرجو توضيح كيفية الانضمام.';return `مرحبًا فريق دعم تأهيل +،\nأنا ${u.name}، ${u.role==='specialist'?u.specialty:roles[u.role]}، ${c?`من مركز ${c.name}`:'من إدارة المنصة'}.\nالبريد: ${u.email}\nرقم الهاتف: ${u.phone||'غير مسجل'}\nأحتاج المساعدة بخصوص: `}
function supportUrl(){const digits=cfg().whatsappNumber.replace(/\D/g,'');return digits.length>=10?`https://wa.me/${digits}?text=${encodeURIComponent(supportMessage())}`:null}
function openSupport(){const url=supportUrl();if(url){window.open(url,'_blank','noopener,noreferrer');return}showModal('التواصل مع دعم تأهيل',`<div class="small-hint">رقم واتساب الدعم المسجّل لدينا (${esc(cfg().displayedPhone)}) غير مكتمل. إلى أن يُضاف الرقم الدولي الكامل، يمكنك التواصل عبر البريد الإلكتروني أو نسخ رسالة الدعم.</div><p class="muted">رسالة جاهزة باسمك وصفتك وبيانات المركز:</p><div class="copy-box" id="support-copy">${esc(supportMessage()).replace(/\n/g,'<br>')}</div><div class="form-actions"><button class="btn btn-outline" data-action="copy-support">نسخ الرسالة</button><a class="btn btn-primary" href="mailto:${esc(cfg().supportEmail)}?subject=${encodeURIComponent('دعم منصة تأهيل +')}&body=${encodeURIComponent(supportMessage())}">${icon('mail')} مراسلة الدعم</a></div>`)}
function marketing(){const email=esc(cfg().supportEmail);return `<div class="marketing plus-marketing"><div class="hero-bg"><nav class="site-nav"><a class="brand" href="/" data-action="landing"><img src="/assets/logo.svg" alt="أيقونة تأهيل +"><span>تأهيل <strong class="brand-plus">+</strong><small>منصة إدارة مراكز التأهيل</small></span></a><div class="site-links"><a href="#features">المميزات</a><a href="#how">كيف تعمل؟</a><a href="#contact">الانضمام</a></div><div class="site-actions"><button class="btn btn-primary" data-action="show-login">${icon('lock')} تسجيل الدخول</button></div></nav><section class="hero plus-hero"><div class="hero-copy"><span class="eyebrow">✦ منصتك الذكية لإدارة مراكز التأهيل</span><div class="hero-mini-brand"><img src="/assets/logo.svg" alt=""><span>تأهيل <em>+</em></span></div><h1>مساحة واحدة<br>لكل <em>خطوة تقدّم.</em></h1><p>إدارة الأطفال والأخصائيين والجلسات والمتابعة والتقارير في تجربة عربية أنيقة؛ وقت أقل في الإدارة، وتركيز أكبر على الرعاية.</p><div class="hero-actions"><button class="btn btn-primary" data-action="show-login">ابدأ من لوحة مركزك ${icon('arrow')}</button><a class="btn btn-outline" href="#contact">طلب الانضمام</a></div><div class="hero-points"><span><i>✓</i> بيانات مستقلة لكل مركز</span><span><i>✓</i> سجلات لا تُحذف</span><span><i>✓</i> من أي جهاز</span></div></div><div class="hero-art plus-art"><div class="float-deco star" aria-hidden="true">⭐</div><div class="float-deco heart" aria-hidden="true">💚</div><div class="float-deco puzzle" aria-hidden="true">🧩</div><img class="therapy-photo" src="/assets/hero-therapy.webp" width="660" height="455" alt="أخصائية تدعم طفلًا أثناء جلسة تعليمية باللعب" loading="eager"><div class="art-floating-card" aria-hidden="true">${icon('shield')} فريقك منظم، وخطواتك أوضح</div></div></section></div><section class="section-wrap" id="features"><div class="section-head"><span class="eyebrow">مصممة ليوم عملك</span><h2>إدارة أسهل. متابعة أدق. نتائج أفضل.</h2><p>كل ما تحتاجه في منصة واحدة، بتصميم يساعد فريقك على الإنجاز ويصون سجل كل جلسة.</p></div><div class="feature-grid">${[['building','إدارة المراكز','حساب مستقل لكل مركز، وتفعيل حصري من الإدارة العامة.'],['users','فريق العمل','أدوار واضحة، تخصصات وكود وظيفي وصور رمزية تلقائية.'],['children','ملفات الأطفال','تشخيصات واختبارات ودراسة حالة وملاحظات الفريق.'],['calendar','جلسات قابلة للمراجعة','تعديل مسموح لصاحب الجلسة، وتاريخ كامل للتغييرات.'],['chart','تقارير لحظية','أعداد الجلسات والساعات والتقدم حسب الأخصائي.'],['shield','خصوصية السجلات','فصل بيانات المراكز، حفظ تاريخ التعديلات دون حذف.']].map(f=>`<article class="feature plus-feature"><div class="feature-icon">${icon(f[0],25)}</div><h3>${f[1]}</h3><p>${f[2]}</p></article>`).join('')}</div></section><div class="steps-wrap" id="how"><section class="section-wrap"><div class="section-head"><span class="eyebrow">3 خطوات فقط</span><h2>من الانضمام إلى أول جلسة</h2></div><div class="steps-grid">${[['01','اطلب تفعيل مركزك','تواصل معنا عبر واتساب لتقديم بيانات مركزك.'],['02','استلم حساب المركز','بعد التفعيل، أضف فريق العمل والأطفال ووزّع الصلاحيات.'],['03','تابع كل جلسة','وثّق الجلسات وراجع التغييرات وصدّر التقارير.']].map(x=>`<div class="step"><strong>${x[0]}</strong><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div></section></div><section class="marketing-cta plus-cta" id="contact"><span class="eyebrow">هل أنت مدير مركز تأهيل؟</span><h2>جاهز تنظم عمل مركزك بثقة؟</h2><p>التفعيل من إدارة المنصة فقط؛ استفسر عن الانضمام برسالة واتساب واحدة.</p><button class="btn btn-primary whatsapp-cta" data-action="support">${icon('phone')} تواصل عبر واتساب</button><p class="contact-secondary">${esc(cfg().displayedPhone)} <span>•</span> <a href="mailto:${email}">${email}</a></p></section><footer class="marketing-footer"><b>تأهيل + © ${new Date().getFullYear()}</b><span>مساحة منظمة لرعاية أفضل — جميع الحقوق محفوظة</span><a href="mailto:${email}" aria-label="البريد الإلكتروني">${icon('mail')} البريد</a></footer></div>`}
function loginPage(){return `<div class="auth-layout"><aside class="auth-side"><a class="brand" href="/" data-action="landing"><img src="/assets/logo.svg" alt="تأهيل +"><span>تأهيل <strong class="brand-plus">+</strong><small>منصة إدارة مراكز التأهيل</small></span></a><div class="login-art" aria-hidden="true"><img src="/assets/hero-therapy.webp" alt=""></div><h2>كل خطوة تقدّم<br>تستحق متابعة أفضل.</h2><p>ملفات الأطفال، والجلسات والتقارير وفريقك في مساحة عمل واحدة منظمة.</p></aside><main class="auth-main"><section class="auth-card"><a class="back" href="/" data-action="landing">${icon('arrow')} الرئيسية</a><span class="eyebrow">مرحبًا بعودتك إلى تأهيل +</span><h1>سجّل دخولك</h1><p>استخدم البريد الإلكتروني لحساب مركزك أو حسابك المهني.</p><form id="login-form" class="form-stack" style="margin-top:27px"><label class="field">البريد الإلكتروني<input type="email" name="email" autocomplete="username" dir="ltr" placeholder="center@example.com" required></label><label class="field">كلمة المرور<div class="password-toggle"><input type="password" name="password" autocomplete="current-password" required><button type="button" data-action="toggle-pass">إظهار</button></div></label><button class="btn btn-primary btn-full" type="submit">تسجيل الدخول ${icon('arrow')}</button></form><div class="hint-note">ليس لديك حساب؟ يتم تفعيل حسابات المراكز عن طريق الإدارة فقط. <a href="/#contact" data-action="landing" class="inline-link">اطلب الانضمام من الصفحة الرئيسية.</a></div></section></main></div>`}
function mustChangePage(){return `<div class="auth-layout"><aside class="auth-side"><div class="brand"><img src="/assets/logo.svg"><span>تأهيل</span></div><h2>حماية حسابك تبدأ من هنا.</h2><p>هذه أول مرة تستخدم فيها الحساب، يرجى استبدال كلمة المرور المؤقتة بكلمة قوية خاصة بك.</p></aside><main class="auth-main"><section class="auth-card"><span class="eyebrow">خطوة أمنية مطلوبة</span><h1>غيّر كلمة المرور</h1><p>الاسم: ${esc(me().name)} — ${esc(me().email)}</p><form id="change-password-form" class="form-stack" style="margin-top:25px"><label class="field">كلمة المرور الحالية<input type="password" name="current" required autocomplete="current-password"></label><label class="field">كلمة المرور الجديدة (12 حرفًا على الأقل)<input type="password" name="next" minlength="12" required autocomplete="new-password"></label><button type="submit" class="btn btn-primary btn-full">حفظ كلمة المرور والدخول</button></form><button class="btn btn-outline btn-full" data-action="logout" style="margin-top:12px">تسجيل الخروج</button></section></main></div>`}
function navItems(){if(superadmin())return ['dashboard','centers','assessments','profile'];if(me().role==='specialist')return ['dashboard','children','sessions',...(assessmentAccess()?.enabled?['assessments']:[]),'profile'];return ['dashboard','team','children','sessions','assessments','reports',...(owner()?['activity','settings']:[]),'profile']}
function shell(){const c=center(),u=me(),nav=navItems();if(!nav.includes(state.page))state.page='dashboard';const title=paths[state.page]?.[0]||'لوحة التحكم';return `<div class="app-layout"><div class="mobile-overlay ${state.mobileOpen?'visible':''}" data-action="close-menu"></div><aside class="sidebar ${state.mobileOpen?'open':''}"><div class="brand"><img src="/assets/logo.svg" alt="تأهيل +"><span>تأهيل <strong class="brand-plus">+</strong><small>مساحة مركزك</small></span></div><div class="side-label">القائمة الرئيسية</div>${nav.map(p=>`<button class="nav-button ${p===state.page?'active':''}" data-action="nav" data-page="${p}">${icon(paths[p][1])}${paths[p][0]}</button>`).join('')}<div class="sidebar-foot"><button data-action="support">${icon('support')} الدعم عبر واتساب</button><button data-action="logout" style="margin-top:7px">${icon('logout')} تسجيل الخروج</button></div></aside><div class="app-main"><header class="app-topbar"><div style="display:flex;gap:12px;align-items:center"><button class="menu-toggle" data-action="toggle-menu" aria-label="فتح القائمة">${icon('menu')}</button><div class="top-title"><small>${c?esc(c.name):'إدارة منصة تأهيل +'}</small><strong>${title}</strong></div></div><div class="top-tools"><div class="top-user">${avatar(u)}<div><b>${esc(u.name)}</b><small>${esc(u.specialty||roles[u.role])}</small></div></div></div></header><main class="content" id="content">${pageHtml()}</main></div></div>`}
function pageHtml(){switch(state.page){case 'centers':return centersView();case 'team':return teamView();case 'children':return childrenView();case 'sessions':return sessionsView();case 'reports':return reportsView();case 'assessments':return assessmentPage({children:state.children,owner:owner(),manager:manager(),globalAdmin:superadmin()});case 'activity':return activityView();case 'settings':return settingsView();case 'profile':return profileView();default:return dashboard()}}
function dashboard(){const u=me(),c=center();if(superadmin())return pageHead('أهلًا بك في إدارة تأهيل +','تحكم في المراكز وتفعيلها وإيقافها وإحصاءاتها',btn(`${icon('plus')} تفعيل مركز جديد`,'new-center'))+`<div class="metric-grid">${stat('المراكز المسجلة',fmtNum(state.centers.length),'على منصة تأهيل +','building')}${stat('المراكز النشطة',fmtNum(state.centers.filter(x=>x.active).length),'حسابات متاحة','shield')}${stat('أعضاء فرق العمل',fmtNum(state.centers.reduce((s,x)=>s+x.staff_count,0)),'كل المراكز','users')}${stat('الجلسات المسجلة',fmtNum(state.centers.reduce((s,x)=>s+x.sessions_count,0)),'كل المراكز','calendar')}</div><section class="panel"><div class="panel-head"><h2>أحدث المراكز</h2>${btn('عرض الكل','nav','soft','data-page="centers"')}</div>${centersTable(state.centers.slice(0,6))}</section><div class="small-hint">حساب الإدارة العامة لإدارة المراكز فقط؛ لا يُسمح له بتصفح ملفات الأطفال الصحية الخاصة بالمراكز.</div>`
const s=state.sessions,minutes=s.reduce((a,x)=>a+Number(x.duration_minutes),0),unique=new Set(s.map(x=>x.child_id)),staff=state.staff.filter(x=>x.role==='specialist'),recent=[...s].slice(0,6)
const banner=`<section class="welcome-banner"><div><span style="color:#adced0;font-size:12px">مرحبًا، ${esc(u.name)}</span><h2>${esc(c?.name||'مرحبًا في تأهيل +')}</h2><p>${manager()?'تابع مركزك وفريقك والجلسات من مساحة عمل موحدة.':'أطفالك المسندون إليك وجلساتك وخطط المتابعة في مكان واحد.'}</p></div>${c?.has_logo?`<img class="center-logo" src="/api/media/center/${esc(c.id)}?v=${state.photoVersion||0}" alt="شعار المركز">`:`<img class="center-logo" src="/assets/logo.svg" alt="تأهيل">`}</section>`
return banner+`<div class="metric-grid">${stat('ملفات الأطفال',fmtNum(state.children.length),manager()?'كل أطفال المركز':'الأطفال المسندون إليك','children')}${stat('جلسات الشهر',fmtNum(s.length),'خلال الشهر المختار','calendar','gold')}${stat('ساعات الجلسات',fmtNum(Math.round(minutes/60*10)/10),'إجمالي العمل المُسجل','clock','navy')}${stat(manager()?'أخصائيون نشطون':'أطفال تمت خدمتهم',fmtNum(manager()?staff.filter(x=>x.active).length:unique.size),'ملخص النشاط','users','rose')}</div><div class="twocol"><section class="panel"><div class="panel-head"><div><h2>أحدث الجلسات</h2><p>أحدث ما تم توثيقه خلال الشهر</p></div>${btn('عرض السجل','nav','soft','data-page="sessions"')}</div>${table(['الطفل','الأخصائي','التاريخ','المدة'],recent.map(x=>`<tr><td><b>${esc(x.child_name)}</b></td><td>${esc(x.specialist_name)}</td><td>${fmtDate(x.started_at)}</td><td>${fmtMinutes(x.duration_minutes)}</td></tr>`),'لا توجد جلسات مسجلة بعد')}</section><section class="panel"><div class="panel-head"><h2>${manager()?'أداء الأخصائيين':'ابدأ بتوثيق جلساتك'}</h2></div>${manager()?performanceBars():`<p class="muted" style="line-height:2">سجّل وقت الجلسة وأهدافها واستجابة الطفل، وسيظهر السجل في ملف الطفل وتقارير المركز مباشرةً.</p>${btn(`${icon('plus')} تسجيل جلسة`,'new-session')}</section>`}</section></div>`
}
function performanceBars(){const r=state.reports.slice(0,6),max=Math.max(1,...r.map(x=>x.session_count));return r.length?`<div class="chart-bars">${r.map(x=>`<div><div class="bar-labels"><b>${esc(x.name)}</b><span>${fmtNum(x.session_count)} جلسة</span></div><div class="bar-track"><div class="bar-fill" style="width:${100*x.session_count/max}%"></div></div></div>`).join('')}</div>`:empty('لا يوجد أخصائيون بعد')}
function centersTable(items){return table(['المركز','المدير / البريد','الفريق','الأطفال','الجلسات','الحالة','الإجراء'],items.map(x=>`<tr><td><div class="cell-person">${x.has_logo?`<span class="avatar"><img src="/api/media/center/${esc(x.id)}" alt=""></span>`:'<span class="avatar">م</span>'}<b>${esc(x.name)}</b></div></td><td dir="ltr">${esc(x.email)}</td><td>${fmtNum(x.staff_count)}</td><td>${fmtNum(x.children_count)}</td><td>${fmtNum(x.sessions_count)}</td><td><span class="tag ${x.active?'':'red'}">${x.active?'نشط':'موقوف'}</span></td><td><div class="card-buttons">${btn(x.active?'إيقاف':'تفعيل','toggle-center',x.active?'danger':'soft',`data-id="${esc(x.id)}" data-active="${!x.active}"`)}${btn('كلمة مرور','reset-center','outline',`data-id="${esc(x.id)}"`)}</div></td></tr>`),'لم تُضف مراكز بعد')}
function centersView(){return pageHead('إدارة المراكز','يمكنك تفعيل مراكز جديدة أو إيقافها مع الاحتفاظ بكل السجلات',btn(`${icon('plus')} إضافة مركز`,'new-center'))+`<section class="panel">${centersTable(state.centers)}</section>`}
function teamView(){const items=state.staff.filter(x=>!state.search||`${x.name} ${x.specialty} ${x.email} ${x.employee_code||''}`.toLowerCase().includes(state.search.toLowerCase()));return pageHead('فريق العمل','أسماء وتخصصات وأدوار واضحة مع الاحتفاظ بكل السجلات',btn(`${icon('plus')} إضافة عضو`,'new-staff'))+`<div class="searchbar"><input class="search-field" placeholder="بحث بالاسم أو التخصص أو البريد أو الكود..." aria-label="بحث في فريق العمل" data-filter="search" value="${esc(state.search)}"><span class="tag gray">${fmtNum(items.length)} عضو</span></div><div class="card-grid">${items.map(x=>`<article class="person-card plus-person-card"><div class="card-top">${avatar(x)}<div><h3>${esc(x.name)}</h3><p>${esc(x.specialty||roles[x.role])}</p><span class="member-role ${x.role==='supervisor'?'green':x.gender==='female'?'pink':'blue'}">${x.role==='supervisor'?'♛ ':''}${esc(roles[x.role])}</span></div></div><div class="info-row"><span>البريد</span><b dir="ltr">${esc(x.email)}</b></div><div class="info-row"><span>الهاتف</span><b>${esc(x.phone||'غير مسجل')}</b></div><div class="info-row"><span>الجنس • الكود</span><b>${x.gender==='female'?'أنثى':'ذكر'} • ${esc(x.employee_code||'—')}</b></div><div class="info-row"><span>الحالة</span><span class="tag ${x.active?'':'red'}">${x.active?'نشط':'موقوف'}</span></div><div class="card-buttons">${(owner()?x.role!=='center_admin':x.role==='specialist')?`${btn('تعديل البيانات','edit-staff','outline',`data-id="${esc(x.id)}"`)}${owner()?btn('إعادة تعيين كلمة المرور','reset-staff','soft',`data-id="${esc(x.id)}"`):''}`:'<span class="muted text-small">الحساب الرئيسي</span>'}</div></article>`).join('')||empty('لا يوجد أعضاء مطابقون')}</div><div class="small-hint">تعطيل الحساب يمنع الدخول ولا يحذف الجلسات السابقة. لا يلزم رفع صور شخصية.</div>`}
function childrenView(){const items=state.children.filter(x=>!state.search||`${x.name} ${x.code} ${x.diagnosis}`.toLowerCase().includes(state.search.toLowerCase()));return pageHead('ملفات الأطفال','كل ملف يحتوي على البيانات الأساسية والتشخيص ودراسة الحالة والاختبارات والجلسات',manager()?btn(`${icon('plus')} إضافة طفل`,'new-child'):'')+`<div class="searchbar"><input class="search-field" placeholder="بحث باسم الطفل أو رقم الملف أو التشخيص..." data-filter="search" aria-label="بحث" value="${esc(state.search)}"><span class="tag gray">${fmtNum(items.length)} ملف</span></div><div class="card-grid">${items.map(c=>`<article class="child-card"><div class="card-top"><span class="avatar">${icon('children')}</span><div><h3>${esc(c.name)}</h3><p>رقم الملف: ${esc(c.code)}</p></div></div><div class="info-row"><span>التشخيص</span><b>${esc(c.diagnosis||'غير محدد')}</b></div><div class="info-row"><span>درجة الذكاء</span><b>${esc(c.iq_score||'غير مسجلة')}</b></div><div class="info-row"><span>الحالة</span><span class="tag ${c.active?'':'red'}">${c.active?'نشط':'مؤرشف'}</span></div><div class="card-buttons">${btn('عرض الملف','view-child','primary',`data-id="${esc(c.id)}"`)}</div></article>`).join('')||empty('لا توجد ملفات أطفال','أضف طفلًا جديدًا أو تحقق من إسناد الأطفال لحسابك')}</div>`}
function sessionStatus(s){return s.status==='needs_review'?'<span class="tag orange">تحتاج مراجعة</span>':s.status==='archived'?'<span class="tag red">مؤرشفة</span>':s.revision_count>0?'<span class="tag blue">معدلة</span>':'<span class="tag">مكتملة</span>'}
function sessionsView(){const s=state.sessions.filter(x=>!state.search||`${x.child_name} ${x.specialist_name} ${x.goals}`.toLowerCase().includes(state.search.toLowerCase()));return pageHead('سجل الجلسات','مراجعة وتعديل مع الاحتفاظ بالتاريخ الكامل ودون حذف نهائي',me().role==='specialist'?btn(`${icon('plus')} جلسة جديدة`,'new-session'):btn(`${icon('download')} تصدير CSV`,'export-sessions','outline'))+`<div class="report-controls"><label>شهر العرض <input type="month" id="month-picker" value="${state.month}"></label><input class="search-field" style="max-width:310px" placeholder="بحث بالطفل أو الأخصائي أو الهدف..." data-filter="search" value="${esc(state.search)}"></div><section class="panel">${table(['الطفل','الأخصائي','رقم الجلسة','البداية','المدة','الحالة','الأهداف','الإجراء'],s.map(x=>`<tr><td><b>${esc(x.child_name)}</b></td><td>${esc(x.specialist_name)}</td><td>${x.session_number?fmtNum(x.session_number):'—'}</td><td>${fmtDate(x.started_at)}</td><td>${fmtMinutes(x.duration_minutes)}</td><td>${sessionStatus(x)}</td><td>${esc(x.goals.slice(0,56))}${x.goals.length>56?'…':''}</td><td>${btn('تفاصيل','view-session','soft',`data-id="${esc(x.id)}"`)}</td></tr>`),'لا توجد جلسات في هذا الشهر')}</section>`}
function reportsView(){const r=state.reports,mins=r.reduce((s,x)=>s+Number(x.minutes),0),total=r.reduce((s,x)=>s+Number(x.session_count),0);return pageHead('التقارير الشهرية','مؤشرات دقيقة لنشاط الأخصائيين وعدد الجلسات والمدد',btn(`${icon('download')} تصدير التقرير`,'export-reports','outline'))+`<div class="report-controls"><label>اختر الشهر <input type="month" id="month-picker" value="${state.month}"></label></div><div class="metric-grid">${stat('جلسات الشهر',fmtNum(total),'جميع الأخصائيين','calendar')}${stat('ساعات العمل',fmtNum(Math.round(mins/60*10)/10),'مجموع الجلسات','clock','gold')}${stat('متوسط الجلسة',fmtNum(total?Math.round(mins/total):0)+' د','بالدقائق','chart','navy')}${stat('أخصائيون قدّموا جلسات',fmtNum(r.filter(x=>x.session_count>0).length),'خلال الشهر','users')}</div><section class="panel"><div class="panel-head"><h2>تقرير تفصيلي لكل أخصائي</h2></div>${table(['الأخصائي','التخصص','اليوم','الشهر','عدد الأطفال','إجمالي المدة','الحالة'],r.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.specialty)}</td><td>${fmtNum(x.today_count)}</td><td>${fmtNum(x.session_count)}</td><td>${fmtNum(x.children_count)}</td><td>${fmtMinutes(x.minutes)}</td><td><span class="tag ${x.active?'':'red'}">${x.active?'نشط':'موقوف'}</span></td></tr>`),'لا يوجد أعضاء لإعداد التقرير')}</section><div class="small-hint">التواريخ الشهرية تعتمد على التوقيت العالمي UTC المخزّن في السجلات. راجع المنطقة الزمنية عند احتساب جلسات حدود منتصف الليل.</div>`}
function activityView(){return pageHead('سجل العمليات','آخر إجراءات إدارة الملفات والحسابات في مركزك')+`<section class="panel">${table(['الإجراء','المستخدم','نوع السجل','الوقت'],state.audit.map(x=>`<tr><td><b>${esc(x.action)}</b></td><td>${esc(x.actor_name||'—')}</td><td>${esc(x.target_type)}</td><td>${fmtDate(x.created_at)}</td></tr>`),'لا يوجد نشاط مسجل')}</section>`}
function settingsView(){const c=center();return pageHead('إعدادات المركز','خصّص اسم المركز وشعاره وبيانات التواصل الظاهرة لفريقك')+`<div class="twocol"><section class="panel"><div class="panel-head"><h2>هوية المركز</h2></div><div class="card-top">${c?.has_logo?`<img src="/api/media/center/${esc(c.id)}?v=${state.photoVersion||0}" class="center-logo" alt="شعار المركز">`:`<img class="center-logo" src="/assets/logo.svg">`}<div><h3>${esc(c?.name)}</h3><p>${esc(c?.email)}</p></div></div><form id="edit-center-form" class="form-stack"><label class="field">اسم المركز<input name="name" value="${esc(c?.name||'')}" required maxlength="120"></label><label class="field">رقم المركز<input name="phone" value="${esc(c?.phone||'')}" maxlength="25"></label><button class="btn btn-primary" type="submit">حفظ بيانات المركز</button></form><div class="divider-line"></div>${btn(`${icon('image')} تغيير شعار المركز`,'upload-center','outline')}</section><section class="panel"><h2>بيانات الحساب</h2><p class="muted">المشرف العام هو المسؤول عن إنشاء حساب المركز وتفعيله.</p><div class="info-row"><span>البريد الرئيسي</span><b>${esc(c?.email)}</b></div><div class="info-row"><span>الحالة</span><b>${c?.active?'نشط':'موقوف'}</b></div><div class="small-hint">يمكنك تعديل اسم المركز وشعاره، لكن البريد الرئيسي لا يتغير من هذه الواجهة حفاظًا على سلامة الحساب.</div></section></div>`}
function profileView(){const u=me();return pageHead('حسابي الشخصي','بيانات حسابك ودورك الذي تعمل به داخل المركز')+`<div class="twocol"><section class="panel"><div class="card-top">${avatar(u)}<div><h3>${esc(u.name)}</h3><p>${esc(u.specialty||roles[u.role])}</p></div></div><div class="info-row"><span>البريد</span><b>${esc(u.email)}</b></div><div class="info-row"><span>رقم الهاتف</span><b>${esc(u.phone||'غير مسجل')}</b></div><div class="info-row"><span>الجهة</span><b>${esc(center()?.name||'الإدارة العامة')}</b></div><div class="card-buttons">${btn(`${icon('lock')} تغيير كلمة المرور`,'change-password','outline')}</div></section><section class="panel"><h2>الدعم الفني</h2><p class="muted" style="line-height:2">عند التواصل، سيتم تجهيز رسالة باسمك وصفتك المهنية واسم مركزك ورقم هاتفك المسجل.</p>${btn(`${icon('support')} التواصل مع الدعم`,'support')}</section></div>`}
function internalNoteModal(id){showModal('ملاحظة داخلية للطفل',`<form id="internal-note-form" data-id="${esc(id)}" class="form-stack">${area('ملاحظة خاصة بمدير المركز والمشرفين','note','',true)}<div class="small-hint">لا تظهر هذه الملاحظة للأخصائيين، وتُضاف لسجل ملف الطفل دون حذف.</div>${saveFooter('إضافة ملاحظة')}</form>`)}
function showModal(title,body,wide=false){closeModal();const div=document.createElement('div');div.id='modal-layer';div.className='modal-layer';div.innerHTML=`<section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-title"><div><h2>${esc(title)}</h2></div><button class="modal-close" type="button" data-action="close-modal" aria-label="إغلاق">×</button></header>${body}</section>`;document.body.append(div);div.addEventListener('mousedown',e=>{if(e.target===div)closeModal()});div.querySelector('input,button,select')?.focus()}
function closeModal(){document.querySelector('#modal-layer')?.remove()}
const field=(label,name,value='',type='text',required=false,extra='')=>`<label class="field">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`
const area=(label,name,value='',required=false)=>`<label class="field form-full">${label}<textarea name="${name}" rows="3" ${required?'required':''}>${esc(value)}</textarea></label>`
const selector=(label,name,options,value='')=>`<label class="field">${label}<select name="${name}">${options.map(o=>`<option value="${esc(typeof o==='string'?o:o[0])}" ${(typeof o==='string'?o:o[0])===value?'selected':''}>${esc(typeof o==='string'?o:o[1])}</option>`).join('')}</select></label>`
const saveFooter=(text='حفظ البيانات')=>`<div class="form-actions"><button class="btn btn-outline" type="button" data-action="close-modal">إلغاء</button><button type="submit" class="btn btn-primary">${icon('check')} ${text}</button></div>`
function newCenterModal(){showModal('تفعيل حساب مركز جديد',`<form id="new-center-form" class="form-grid">${field('اسم المركز','name','','text',true,'maxlength="120" placeholder="مثال: مركز حكايات طفل"')}${field('اسم مدير المركز','manager_name','','text',true)}${field('بريد المركز الأساسي','email','','email',true,'dir="ltr"')}${field('رقم هاتف المركز','phone','','tel',false)}${field('كلمة مرور مؤقتة (12 حرفًا على الأقل)','password','','password',true,'minlength="12" autocomplete="new-password"')}<div class="small-hint form-full">سيتم إنشاء المركز وحساب مديره بالبريد المسجّل، ولا يوجد تسجيل ذاتي. يجب على مدير المركز تغيير كلمة المرور عند أول دخول. أرسل بيانات الدخول عبر وسيلة خاصة وآمنة.</div><div class="form-full">${saveFooter('إنشاء وتفعيل المركز')}</div></form>`,true)}
function staffModal(target){const edit=!!target,canSuper=owner();showModal(edit?'تعديل حساب العضو':'إضافة عضو للفريق',`<form id="${edit?'edit-staff-form':'new-staff-form'}" class="form-grid" ${edit?`data-id="${esc(target.id)}"`:''}>${field('الاسم الكامل','name',target?.name,'text',true)}${field('البريد الإلكتروني','email',target?.email,'email',true,'dir="ltr"')}${edit?`<div class="field"><b>نوع الحساب</b><span class="tag gray">${roles[target.role]}</span></div>`:selector('نوع العضو','role',[['specialist','أخصائي'],...(canSuper?[['supervisor','مشرف']]:[])],'specialist')}${selector('الجنس','gender',[['male','ذكر'],['female','أنثى']],target?.gender||'male')}${selector('التخصص','specialty',['',...specialities],target?.specialty||'')}${field('رقم الهاتف','phone',target?.phone,'tel')}${field('الكود الوظيفي','employee_code',target?.employee_code,'text',false,'maxlength="40"')}${edit?selector('حالة الحساب','active',[['true','نشط'],['false','موقوف']],String(!!target.active)):field('كلمة المرور المؤقتة (12 حرفًا على الأقل)','password','','password',true,'minlength="12" autocomplete="new-password"')}<div class="small-hint form-full">الصورة الرمزية تُنشأ تلقائيًا حسب الدور والجنس. إيقاف الحساب لا يحذف الجلسات السابقة.</div><div class="form-full">${saveFooter(edit?'حفظ التعديلات':'إضافة الحساب')}</div></form>`,true)}
function childModal(child){const edit=!!child;showModal(edit?'تعديل ملف الطفل':'إضافة ملف طفل',`<form id="${edit?'edit-child-form':'new-child-form'}" class="form-grid" ${edit?`data-id="${esc(child.id)}"`:''}>${field('اسم الطفل','name',child?.name,'text',true)}${field('رقم الملف','code',child?.code,'text',true)}${field('تاريخ الميلاد','birth_date',child?.birth_date,'date')}${field('التشخيص','diagnosis',child?.diagnosis)}${field('درجة الذكاء (إن وجدت)','iq_score',child?.iq_score)}${field('اسم ولي الأمر','guardian_name',child?.guardian_name)}${field('رقم ولي الأمر','guardian_phone',child?.guardian_phone,'tel')}${edit?selector('حالة الملف','active',[['true','نشط'],['false','مؤرشف']],String(!!child.active)):''}${area('ملخص دراسة الحالة والملاحظات الأساسية','case_summary',child?.case_summary)}<div class="form-full">${saveFooter(edit?'حفظ الملف':'حفظ الطفل')}</div></form>`,true)}
async function openChild(id){const data=await api(`/children/${id}`);if(assessmentAccess()?.enabled){try{const result=await api('/assessments?child_id='+encodeURIComponent(id));data.assessments=result.items}catch(e){if(e.status!==403)throw e;data.assessments=[]}}else data.assessments=[];state.detail=data;showChildDetails()}
function showChildDetails(){const {child:c,tests,assignments,sessions=[],assessments=[]}=state.detail;const testSection=tests.length?table(['الاختبار','النتيجة','التاريخ','ملاحظات'],tests.map(t=>`<tr><td><b>${esc(t.test_name)}</b></td><td>${esc(t.result)}</td><td>${esc(t.test_date||'—')}</td><td>${esc(t.notes||'—')}</td></tr>`),'لا توجد اختبارات'):empty('لم تسجل اختبارات بعد')
const ass=assignments.length?assignments.map(x=>`<span class="tag">${esc(x.name)} — ${esc(x.specialty)}</span>`).join(' '):'<span class="muted">لم يُسند لأي أخصائي</span>'
showModal(`ملف الطفل: ${c.name}`,`<div class="tab-segment"><button type="button" class="active" data-action="child-tab" data-tab="base">البيانات</button><button type="button" data-action="child-tab" data-tab="tests">الاختبارات</button><button type="button" data-action="child-tab" data-tab="assignment">الأخصائيون</button><button type="button" data-action="child-tab" data-tab="sessions">الجلسات</button></div>${assessmentAccess()?.enabled?`<div class="assessment-child-preview"><b>${assessments.length?'آخر تقييم مسجل: '+esc(assessments[0].program_name):'لم يُقيّم الطفل بعد'}</b><span>${assessments.length?'بتاريخ '+fmtDate(assessments[0].created_at)+' — '+esc(assessments[0].assessor_name):'يمكن البدء بتقييم الطفل من قائمة البرامج'}</span>${btn('التقييمات والخطة','assess-child-open','soft',`data-id="${esc(c.id)}"`)}</div>`:''}<div id="child-tab-base"><div class="detail-list">${[['رقم الملف',c.code],['تاريخ الميلاد',c.birth_date||'—'],['التشخيص',c.diagnosis||'—'],['درجة الذكاء',c.iq_score||'غير مسجلة'],['اسم ولي الأمر',manager()?c.guardian_name||'—':'مقيد للمشرف'],['رقم ولي الأمر',manager()?c.guardian_phone||'—':'مقيد للمشرف']].map(x=>`<div class="detail-item"><small>${x[0]}</small><b>${esc(x[1])}</b></div>`).join('')}</div><h3 class="section-subtitle">ملخص دراسة الحالة</h3><div class="notes-box">${esc(c.case_summary||'لم يُسجل ملخص بعد')}</div>${manager()?`<div class="form-actions">${btn(`${icon('edit')} تعديل الملف`,'edit-child','outline',`data-id="${esc(c.id)}"`)}</div>`:''}${manager()?`<h3 class="section-subtitle">ملاحظات داخلية للإدارة</h3><div class="notes-box">${(state.detail.internal_notes||[]).map(n=>`<div class="private-note"><strong>${esc(n.author_name)}</strong> <small>${fmtDate(n.created_at)}</small><p>${esc(n.note)}</p></div>`).join('')||'<span class="muted">لا توجد ملاحظات داخلية</span>'}</div><div class="form-actions">${btn('إضافة ملاحظة خاصة','internal-note','outline',`data-id="${esc(c.id)}"`)}</div>`:''}</div><div id="child-tab-tests" hidden><div style="margin-bottom:15px">${manager()?btn(`${icon('plus')} إضافة اختبار`,'new-test','soft',`data-id="${esc(c.id)}"`):''}</div>${testSection}</div><div id="child-tab-assignment" hidden><h3 class="section-subtitle">الأخصائيون المسندون</h3><div class="specialty-list">${ass}</div>${manager()?`<div class="form-actions">${btn('تعديل إسناد الطفل','assign-child','primary',`data-id="${esc(c.id)}"`)}</div>`:''}</div><div id="child-tab-sessions" hidden>${sessions.length?table(['رقم الجلسة','التاريخ','الأخصائي','المدة','الأهداف'],sessions.map(x=>`<tr><td>${x.session_number?fmtNum(x.session_number):'—'}</td><td>${fmtDate(x.started_at)}</td><td>${esc(x.specialist_name)}</td><td>${fmtNum(x.duration_minutes)} دقيقة</td><td><b>${esc(x.goals)}</b><div class="muted">${esc(x.activities||'')}</div></td></tr>`),'لا توجد جلسات'):empty('لا توجد جلسات سابقة لهذا الطفل')}</div>`,true)}
function testModal(id){showModal('إضافة اختبار للطفل',`<form id="new-test-form" class="form-grid" data-id="${esc(id)}">${field('اسم الاختبار','test_name','','text',true)}${field('تاريخ الاختبار','test_date',new Date().toISOString().slice(0,10),'date')}${area('نتيجة الاختبار','result','',true)}${area('ملاحظات الاختبار','notes')}<div class="form-full">${saveFooter('حفظ الاختبار')}</div></form>`)}
function assignmentModal(id){const selected=new Set(state.detail?.assignments.map(x=>x.specialist_id)||[]),members=state.staff.filter(x=>x.role==='specialist'&&x.active);showModal('إسناد الطفل للأخصائيين',`<form id="assign-form" data-id="${esc(id)}"><p class="muted" style="line-height:1.9">حدد الأخصائيين المسموح لهم بعرض ملف الطفل وإضافة جلساته. إلغاء الإسناد يمنع الأخصائي من الوصول للملف لاحقًا.</p><div class="form-stack">${members.length?members.map(x=>`<label style="display:flex;gap:13px;align-items:center;padding:12px;border:1px solid #e6eeee;border-radius:12px;cursor:pointer"><input type="checkbox" name="specialist_ids" value="${esc(x.id)}" ${selected.has(x.id)?'checked':''}>${avatar(x)}<span><b>${esc(x.name)}</b><br><small class="muted">${esc(x.specialty)}</small></span></label>`).join(''):empty('لا يوجد أخصائيون نشطون')}</div>${saveFooter('حفظ الإسناد')}</form>`)}
function newSessionModal(item){const edit=!!item,items=state.children.filter(x=>x.active),now=localTime(),start=localTime(-45);const d=s=>{if(!s)return '';const dt=new Date(s);return new Date(dt.getTime()-dt.getTimezoneOffset()*60000).toISOString().slice(0,16)};showModal(edit?'تعديل الجلسة المسجلة':'تسجيل جلسة جديدة',`<form id="${edit?'edit-session-form':'new-session-form'}" class="form-grid" ${edit?`data-id="${esc(item.id)}"`:''}>${edit?`<div class="small-hint form-full">الطفل: <b>${esc(item.child_name)}</b> — لا يمكن تغيير الطفل أو الأخصائي بعد إنشاء الجلسة.</div><input name="expected_revision" type="hidden" value="${Number(item.revision_count||0)}">`:`<label class="field">اختر الطفل<select name="child_id" required>${items.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} — ${esc(x.code)}</option>`).join('')}</select></label>`}<label class="field">رقم الجلسة<select name="session_number" required>${Array.from({length:25},(_,i)=>i+1).map(n=>`<option value="${n}" ${Number(item?.session_number||1)===n?'selected':''}>الجلسة ${fmtNum(n)}</option>`).join('')}</select></label>${field('وقت البداية','started_at',edit?d(item.started_at):start,'datetime-local',true)}${field('وقت النهاية','ended_at',edit?d(item.ended_at):now,'datetime-local',true)}<div class="small-hint form-full">مدة الجلسة تُحسب تلقائيًا من التوقيت المسجل (الحد الأقصى 8 ساعات).</div>${area('الأهداف','goals',item?.goals||'',true)}${area('الأنشطة والاستراتيجيات','activities',item?.activities||'')}${area('استجابة الطفل','child_response',item?.child_response||'')}${area('ملاحظات الجلسة','notes',item?.notes||'')}${area('خطة الجلسة التالية','next_plan',item?.next_plan||'')}${edit?area('سبب التعديل (إلزامي للتوثيق)','reason','',true):''}<div class="form-full">${saveFooter(edit?'حفظ التعديل وتوثيقه':'تسجيل الجلسة')}</div></form>`,true)}
function sessionDetails(id){const s=state.sessions.find(x=>x.id===id);if(!s)return;const fields=[['الطفل',s.child_name],['الأخصائي',s.specialist_name],['رقم الجلسة',Number(s.session_number)>0?fmtNum(s.session_number):'غير محدد'],['البداية',new Date(s.started_at).toLocaleString('ar-EG')],['النهاية',new Date(s.ended_at).toLocaleString('ar-EG')],['المدة',fmtMinutes(s.duration_minutes)],['الأهداف',s.goals],['الأنشطة',s.activities],['استجابة الطفل',s.child_response],['الملاحظات',s.notes],['خطة المتابعة',s.next_plan]];const actions=`<div class="form-actions">${me().role==='specialist'&&s.status!=='archived'?btn(`${icon('edit')} تعديل جلستي`,'edit-session','primary',`data-id="${esc(s.id)}"`):''}${btn('سجل التغييرات','session-history','outline',`data-id="${esc(s.id)}"`)}${manager()?btn('مراجعة / أرشفة','review-session','soft',`data-id="${esc(s.id)}"`):''}</div>`;showModal('تفاصيل الجلسة',`<div class="status-bar">${sessionStatus(s)} ${Number(s.revision_count)?`<span class="muted">عدد التعديلات: ${fmtNum(s.revision_count)}</span>`:''}</div><div class="detail-list">${fields.map(x=>`<div class="detail-item" style="${x[0].length>9?'grid-column:1/-1':''}"><small>${x[0]}</small><b>${esc(x[1]||'—')}</b></div>`).join('')}</div>${s.review_note?`<div class="small-hint">ملاحظة المراجعة: ${esc(s.review_note)}</div>`:''}${actions}<p class="muted text-small">التعديل لا يحذف النسخ السابقة، ولا توجد وظيفة حذف نهائي للجلسات.</p>`,true)}
function reviewSessionModal(id){const item=state.sessions.find(x=>x.id===id);if(!item)return;showModal('مراجعة الجلسة',`<form id="review-session-form" data-id="${esc(item.id)}" class="form-stack">${selector('حالة الجلسة','status',[['completed','مكتملة'],['needs_review','تحتاج مراجعة'],['archived','مؤرشفة (دون حذف)']],item.status||'completed')}${area('ملاحظة داخلية للمراجعة','note',item.review_note||'')}<div class="small-hint">الأرشفة لا تحذف محتوى الجلسة، وتمنع تعديلها من الأخصائي وتستبعدها من إجمالي التقارير.</div>${saveFooter('حفظ المراجعة')}</form>`)}
async function sessionHistory(id){const data=await api('/sessions/'+id+'/history');showModal('تاريخ تعديلات الجلسة',data.items.length?`<div class="history-list">${data.items.map((h,i)=>`<article class="history-item"><div class="history-head"><b>تعديل ${fmtNum(data.items.length-i)} — ${esc(h.editor_name)}</b><small>${new Date(h.created_at+'Z').toLocaleString('ar-EG')}</small></div><p><strong>السبب:</strong> ${esc(h.reason)}</p><details><summary>عرض النسخة السابقة والتغييرات</summary><div class="detail-list">${[['رقم الجلسة',h.before.session_number||'غير محدد'],['البداية',h.before.started_at],['النهاية',h.before.ended_at],['الأهداف',h.before.goals],['الأنشطة',h.before.activities],['استجابة الطفل',h.before.child_response],['الملاحظات',h.before.notes],['الخطة',h.before.next_plan]].map(x=>`<div class="detail-item"><small>${x[0]} قبل التعديل</small><b>${esc(x[1]||'—')}</b></div>`).join('')}</div></details></article>`).join('')}</div>`:empty('لم تُعدَّل هذه الجلسة بعد','أي تعديل سيظهر هنا باسمه ووقته وسببه'),true)}
function photoModal(kind,id){showModal(kind==='center'?'رفع شعار المركز':'تغيير الصورة الشخصية',`<form id="upload-form" data-kind="${esc(kind)}" data-id="${esc(id||'')}"><label class="file-pick">${icon('image')}<div><b>اختر صورة الشعار أو الحساب</b><div class="muted text-small">JPEG أو PNG أو WebP، حتى 1.5 ميجابايت</div></div><input name="file" type="file" accept="image/png,image/jpeg,image/webp" required></label><div id="photo-preview"></div>${saveFooter('رفع الصورة')}</form>`)}
function resetCenterModal(id){const target=state.centers.find(x=>x.id===id);if(!target)return;showModal(`استعادة دخول مركز ${target.name}`,`<form id="reset-center-form" data-id="${esc(id)}" class="form-stack">${field('كلمة مرور مؤقتة جديدة','password','','password',true,'minlength="12"')}<div class="small-hint">سيتم تسجيل خروج مدير المركز من الأجهزة السابقة، وإلزامه بتغيير كلمة المرور المؤقتة عند الدخول التالي.</div>${saveFooter('استعادة دخول المركز')}</form>`)}
function resetPasswordModal(id){const target=state.staff.find(x=>x.id===id);if(!target)return;showModal(`تعيين كلمة مرور: ${target.name}`,`<form id="reset-staff-form" data-id="${esc(id)}" class="form-stack">${field('كلمة المرور المؤقتة الجديدة','password','','password',true,'minlength="12"')}<div class="small-hint">سيتم تسجيل خروج العضو من كل أجهزته، وسيُطلب منه تغيير كلمة المرور عند تسجيل الدخول التالي. لا تُرسل كلمات المرور في مجموعة عامة.</div>${saveFooter('تحديث كلمة المرور')}</form>`)}
function changePasswordModal(){showModal('تغيير كلمة المرور',`<form id="change-password-form" class="form-stack">${field('كلمة المرور الحالية','current','','password',true)}${field('كلمة المرور الجديدة','next','','password',true,'minlength="12"')}${saveFooter('تغيير كلمة المرور')}</form>`)}
function render(){if(!state.auth)root.innerHTML=state.loginMode?loginPage():marketing();else if(me().must_change_password)root.innerHTML=mustChangePage();else root.innerHTML=shell();document.title=`${state.auth?paths[state.page]?.[0]+' | ':''}تأهيل + — إدارة مراكز التأهيل`}
async function hydrate(){const u=me(),m=state.month;const jobs=superadmin()?[api('/centers')]:[api('/children'),api('/sessions?month='+m),...(manager()?[api('/staff'),api('/reports?month='+m)]:[]),...(owner()?[api('/audit')]:[])];const res=await Promise.all(jobs);if(superadmin()){state.centers=res[0].items}else{let i=0;state.children=res[i++].items;state.sessions=res[i++].items;if(manager()){state.staff=res[i++].items;state.reports=res[i++].items}if(owner())state.audit=res[i++].items;await assessmentAccessLoad(api)}render()}
async function refreshAccount(){state.auth=await api('/auth/me');await hydrate()}
async function changePage(page){state.page=page;state.search='';state.mobileOpen=false;if(page==='assessments'){if(superadmin()){await assessmentAccessLoad(api);await assessmentPlatformLoad(api)}else {await assessmentAccessLoad(api);await assessmentsLoad(api)}}render();window.scrollTo({top:0,behavior:'auto'})}
function formValues(form){const obj=Object.fromEntries(new FormData(form).entries());return obj}
async function submitHandler(e){const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();if(state.busy)return;state.busy=true;const button=form.querySelector('[type=submit]'),label=button?.innerHTML;if(button){button.disabled=true;button.innerHTML='جارٍ الحفظ...'}
try{
 const b=formValues(form)
 switch(form.id){
  case 'login-form':state.auth=await api('/auth/login','POST',b);state.loginMode=false;state.page='dashboard';state.search='';if(me().must_change_password)render();else await hydrate();notice(`مرحبًا بك، ${me().name}`);break
  case 'change-password-form':await api('/auth/change-password','POST',b);closeModal();await refreshAccount();notice('تم تغيير كلمة المرور بنجاح');break
  case 'new-center-form':await api('/centers','POST',b);closeModal();await hydrate();notice('تم تفعيل المركز وإنشاء حسابه الأساسي');break
  case 'new-staff-form':if(b.role==='specialist'&&!b.specialty.trim())throw Error('اختر تخصص الأخصائي');await api('/staff','POST',b);closeModal();await hydrate();notice('تم إنشاء الحساب والصورة الرمزية تلقائية');break
  case 'edit-staff-form':await api('/staff/'+form.dataset.id,'PATCH',{name:b.name,email:b.email,gender:b.gender,employee_code:b.employee_code,phone:b.phone,specialty:b.specialty,active:b.active==='true'});closeModal();await hydrate();notice('تم تحديث العضو وحالة وصوله');break
  case 'new-child-form':await api('/children','POST',b);closeModal();await hydrate();notice('تم حفظ ملف الطفل');break
  case 'edit-child-form':await api('/children/'+form.dataset.id,'PATCH',{...b,active:b.active==='true'});closeModal();await hydrate();notice('تم تحديث ملف الطفل');break
  case 'new-test-form':await api('/children/'+form.dataset.id+'/tests','POST',b);await hydrate();await openChild(form.dataset.id);notice('تم حفظ الاختبار');break
  case 'assign-form':await api('/children/'+form.dataset.id+'/assignments','PUT',{specialist_ids:[...form.querySelectorAll('input[name=specialist_ids]:checked')].map(el=>el.value)});await hydrate();await openChild(form.dataset.id);notice('تم تحديث إسناد الأخصائيين');break
  case 'new-session-form':{
   const start=new Date(b.started_at),end=new Date(b.ended_at)
   if(!(end>start))throw Error('وقت النهاية يجب أن يكون بعد البداية')
   await api('/sessions','POST',{...b,started_at:start.toISOString(),ended_at:end.toISOString()});closeModal();await hydrate();notice('تم حفظ الجلسة وتوثيق وقتها وأهدافها');break
  }
  case 'edit-session-form':{
       const start=new Date(b.started_at),end=new Date(b.ended_at)
       if(!(end>start))throw Error('وقت النهاية يجب أن يكون بعد البداية')
       await api('/sessions/'+form.dataset.id,'PATCH',{...b,started_at:start.toISOString(),ended_at:end.toISOString(),expected_revision:Number(b.expected_revision)});closeModal();await hydrate();notice('تم حفظ تعديل الجلسة مع تسجيل النسخة السابقة');break
      }
      case 'review-session-form':await api('/sessions/'+form.dataset.id+'/review','PATCH',b);closeModal();await hydrate();notice('تم تحديث حالة مراجعة الجلسة');break
      case 'internal-note-form':await api('/children/'+form.dataset.id+'/internal-notes','POST',b);await hydrate();await openChild(form.dataset.id);notice('تمت إضافة الملاحظة الداخلية');break
      case 'edit-center-form':await api('/center','PATCH',b);await refreshAccount();notice('تم تحديث هوية المركز');break
  case 'reset-center-form':await api('/centers/'+form.dataset.id+'/reset-password','POST',b);closeModal();notice('تم تعيين كلمة مرور مؤقتة جديدة لمدير المركز');break
  case 'reset-staff-form':await api('/staff/'+form.dataset.id+'/reset-password','POST',b);closeModal();notice('تم تغيير كلمة المرور المؤقتة وإغلاق جلسات الدخول القديمة');break
  case 'upload-form':{
   const image=form.querySelector('input[type=file]').files[0];if(!image)throw Error('اختر صورة');if(image.size>1500000)throw Error('الصورة أكبر من 1.5 ميجابايت')
   const data=new FormData();data.append('file',image);data.append('kind',form.dataset.kind);data.append('id',form.dataset.id)
   await api('/media/upload','POST',data);state.photoVersion=Date.now();closeModal();await refreshAccount();notice('تم تحديث الصورة');break
  }
 }
}catch(err){notice(err.message||'لم تكتمل العملية',true)}finally{state.busy=false;if(button?.isConnected){button.disabled=false;button.innerHTML=label}}
}
async function actionHandler(e){const trigger=e.target.closest?.('[data-action]');if(!trigger)return;const action=trigger.dataset.action
if(trigger.tagName==='A')e.preventDefault()
try{if(action==='assess-child-open'){assessmentSelectChild(trigger.dataset.id);closeModal();await changePage('assessments');return}if(action.startsWith('assess-')){await assessmentAction(trigger,{api,notice,render,children:state.children,manager:manager(),owner:owner(),platformAdmin:superadmin()});return}switch(action){
 case 'landing':state.loginMode=false;state.search='';render();window.scrollTo(0,0);break
 case 'show-login':state.loginMode=true;render();window.scrollTo(0,0);break
 case 'support':openSupport();break
 case 'copy-support':await navigator.clipboard.writeText(supportMessage());notice('تم نسخ رسالة الدعم');break
 case 'toggle-pass':{const input=trigger.parentElement.querySelector('input');input.type=input.type==='password'?'text':'password';trigger.textContent=input.type==='password'?'إظهار':'إخفاء';break}
 case 'nav':await changePage(trigger.dataset.page);break
 case 'toggle-menu':state.mobileOpen=!state.mobileOpen;render();break
 case 'close-menu':state.mobileOpen=false;render();break
 case 'close-modal':closeModal();break
 case 'logout':await api('/auth/logout','POST');state.auth=null;state.loginMode=false;state.staff=[];state.children=[];state.sessions=[];closeModal();render();notice('تم تسجيل الخروج');break
 case 'new-center':newCenterModal();break
 case 'toggle-center':{const id=trigger.dataset.id,on=trigger.dataset.active==='true';if(!confirm(on?'هل تريد إعادة تفعيل هذا المركز؟':'هل تريد إيقاف المركز وجميع حساباته؟'))return;await api('/centers/'+id+'/status','PATCH',{active:on});await hydrate();notice(on?'تم تفعيل المركز':'تم إيقاف المركز');break}
 case 'reset-center':resetCenterModal(trigger.dataset.id);break
 case 'new-staff':staffModal();break
 case 'edit-staff':staffModal(state.staff.find(x=>x.id===trigger.dataset.id));break
 case 'photo-staff':notice('الصور الشخصية مستبدلة برموز تلقائية');break
 case 'photo-self':notice('الصور الشخصية مستبدلة برموز تلقائية');break
 case 'upload-center':photoModal('center');break
 case 'reset-staff':resetPasswordModal(trigger.dataset.id);break
 case 'new-child':childModal();break
 case 'edit-child':{const c=state.detail?.child?.id===trigger.dataset.id?state.detail.child:state.children.find(x=>x.id===trigger.dataset.id);childModal(c);break}
 case 'view-child':await openChild(trigger.dataset.id);break
 case 'child-tab':for(const tab of ['base','tests','assignment','sessions']){document.querySelector('#child-tab-'+tab).hidden=trigger.dataset.tab!==tab}document.querySelectorAll('.tab-segment button').forEach(b=>b.classList.toggle('active',b===trigger));break
 case 'new-test':testModal(trigger.dataset.id);break
 case 'assign-child':assignmentModal(trigger.dataset.id);break
 case 'new-session':if(!state.children.some(x=>x.active)){notice('لا يوجد أطفال مسندون إليك لتسجيل جلسة',true);break}newSessionModal();break
 case 'edit-session':newSessionModal(state.sessions.find(x=>x.id===trigger.dataset.id));break
 case 'review-session':reviewSessionModal(trigger.dataset.id);break
 case 'session-history':await sessionHistory(trigger.dataset.id);break
 case 'internal-note':internalNoteModal(trigger.dataset.id);break
 case 'view-session':sessionDetails(trigger.dataset.id);break
 case 'change-password':changePasswordModal();break
 case 'export-reports':csvDownload([['الاسم','التخصص','جلسات اليوم','جلسات الشهر','الأطفال','إجمالي الدقائق','الحالة'],...state.reports.map(x=>[x.name,x.specialty,x.today_count,x.session_count,x.children_count,x.minutes,x.active?'نشط':'موقوف'])],`taheel-report-${state.month}.csv`);notice('تم تجهيز التقرير');break
 case 'export-sessions':csvDownload([['الطفل','الأخصائي','رقم الجلسة','البداية','النهاية','المدة بالدقائق','الأهداف','الأنشطة','الاستجابة','الملاحظات','الخطة التالية'],...state.sessions.map(x=>[x.child_name,x.specialist_name,x.session_number||'',x.started_at,x.ended_at,x.duration_minutes,x.goals,x.activities,x.child_response,x.notes,x.next_plan])],`taheel-sessions-${state.month}.csv`);notice('تم تجهيز ملف الجلسات — احتفظ به في مكان آمن');break
 }}catch(err){notice(err.message||'حدث خطأ في العملية',true)}
}
document.addEventListener('click',actionHandler)
document.addEventListener('submit',submitHandler)
document.addEventListener('change',async e=>{try{if(await assessmentChange(e.target,{api,notice,render}))return}catch(err){notice(err.message||'تعذر حفظ التقييم',true)}if(e.target.id==='month-picker'){const v=e.target.value;if(/^20\d\d-\d\d$/.test(v)){state.month=v;try{await hydrate()}catch(err){notice(err.message,true)}}}if(e.target.matches('[data-filter=search]')){state.search=e.target.value;render()}if(e.target.matches('input[type=file]')){const file=e.target.files[0],target=document.querySelector('#photo-preview');if(file&&target){const url=URL.createObjectURL(file);target.innerHTML=`<img class="preview-thumb" alt="معاينة الصورة">`;target.querySelector('img').src=url;target.querySelector('img').onload=()=>URL.revokeObjectURL(url)}}})
async function init(){try{state.auth=await api('/auth/me');if(me().must_change_password)render();else await hydrate()}catch(err){if(err.status!==401){console.error('Initialization:',err.message);notice('تعذر الاتصال بالمنصة؛ تحقق من إعدادها أو من اتصال الإنترنت',true)}state.auth=null;render()}}
init()

// Filter immediately while typing, keeping the search field focused after refreshing cards.
document.addEventListener('input',e=>{if(!e.target.matches?.('[data-filter=search]'))return;const pos=e.target.selectionStart;state.search=e.target.value;render();const field=root.querySelector('[data-filter=search]');if(field){field.focus();try{field.setSelectionRange(pos,pos)}catch{}}})
